import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.dirname(fileURLToPath(import.meta.url));
const dbPath = process.env.DB_PATH || path.join(root, 'workboard.sqlite');
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  archived INTEGER NOT NULL DEFAULT 0
)`);
try { db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch {}
const getProject = db.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const setArchived = db.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = db.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
const createProject = db.prepare('INSERT INTO projects (name) VALUES (?)');
db.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
)`);
const listTasks = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = db.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const getTask = db.prepare('SELECT id, project_id AS projectId, title, completed FROM tasks WHERE id = ?');
const updateTask = db.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const listProjects = db.prepare(`SELECT p.id, p.name, p.archived,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completedCount,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS totalCount
  FROM projects p ORDER BY p.id`);

const send = (res, status, body, type = 'application/json; charset=utf-8') => {
  res.writeHead(status, { 'Content-Type': type, 'X-Content-Type-Options': 'nosniff' });
  res.end(body);
};
const json = (res, status, value) => send(res, status, JSON.stringify(value));

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  if (req.method === 'GET' && url.pathname === '/health') {
    return json(res, 200, { status: 'ok' });
  }
  if (url.pathname === '/api/projects' && req.method === 'GET') {
    return json(res, 200, listProjects.all());
  }
  if (url.pathname === '/api/projects' && req.method === 'POST') {
    let raw = '';
    try {
      for await (const chunk of req) raw += chunk;
      const data = JSON.parse(raw || '{}');
      const name = typeof data.name === 'string' ? data.name.trim() : '';
      if (!name) return json(res, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return json(res, 201, getProject.get(Number(result.lastInsertRowid)));
    } catch {
      return json(res, 400, { error: 'Invalid request' });
    }
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/?$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    if (!getProject.get(projectId)) return json(res, 404, { error: 'Project not found' });
    if (req.method === 'GET') return json(res, 200, listTasks.all(projectId));
    if (req.method === 'POST') {
      if (getProject.get(projectId).archived) return json(res, 403, { error: 'Archived project' });
      try {
        let raw = '';
        for await (const chunk of req) raw += chunk;
        const data = JSON.parse(raw || '{}');
        const title = typeof data.title === 'string' ? data.title.trim() : '';
        if (!title) return json(res, 400, { error: 'Task title is required' });
        const result = createTask.run(projectId, title);
        return json(res, 201, getTask.get(Number(result.lastInsertRowid)));
      } catch {
        return json(res, 400, { error: 'Invalid request' });
      }
    }
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/?$/);
  if (archiveMatch && req.method === 'PATCH') {
    try {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      const data = JSON.parse(raw || '{}');
      const id = Number(archiveMatch[1]);
      const project = getProject.get(id);
      if (!project) return json(res, 404, { error: 'Project not found' });
      if (typeof data.name === 'string') {
        const name = data.name.trim();
        if (!name) return json(res, 400, { error: 'Project name is required' });
        if (project.archived) return json(res, 403, { error: 'Archived project' });
        renameProject.run(name, id);
      } else if (typeof data.archived === 'boolean') {
        setArchived.run(data.archived ? 1 : 0, id);
      } else return json(res, 400, { error: 'Invalid project update' });
      return json(res, 200, getProject.get(id));
    } catch { return json(res, 400, { error: 'Invalid request' }); }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/?$/);
  if (taskMatch && req.method === 'PATCH') {
    try {
      let raw = '';
      for await (const chunk of req) raw += chunk;
      const data = JSON.parse(raw || '{}');
      if (typeof data.completed !== 'boolean') return json(res, 400, { error: 'Invalid completion state' });
      const result = updateTask.run(data.completed ? 1 : 0, Number(taskMatch[2]), Number(taskMatch[1]));
      if (!result.changes) return json(res, 404, { error: 'Task not found' });
      return json(res, 200, getTask.get(Number(taskMatch[2])));
    } catch {
      return json(res, 400, { error: 'Invalid request' });
    }
  }

  const projectMatch = url.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (req.method === 'GET' && projectMatch) {
    const project = getProject.get(Number(projectMatch[1]));
    if (!project) return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
  }
  if (req.method === 'GET' && (url.pathname === '/' || projectMatch)) {
    try {
      const html = await readFile(path.join(root, 'public', 'index.html'));
      return send(res, 200, html, 'text/html; charset=utf-8');
    } catch {
      return send(res, 500, 'Application unavailable', 'text/plain; charset=utf-8');
    }
  }
  if (req.method === 'GET' && url.pathname === '/app.js') {
    try {
      return send(res, 200, await readFile(path.join(root, 'public', 'app.js')), 'text/javascript; charset=utf-8');
    } catch {
      return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
    }
  }
  if (req.method === 'GET' && url.pathname === '/styles.css') {
    try {
      return send(res, 200, await readFile(path.join(root, 'public', 'styles.css')), 'text/css; charset=utf-8');
    } catch {
      return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
    }
  }
  return send(res, 404, 'Not found', 'text/plain; charset=utf-8');
});

const port = Number(process.env.PORT) || 8080;
server.listen(port, '0.0.0.0');

const listSection = document.querySelector('#project-list');
const detailSection = document.querySelector('#project-detail');
const projectContainer = document.querySelector('#projects');
const errorMessage = document.querySelector('#error-message');
const taskContainer = document.querySelector('#tasks');
let activeProjectId = null;
let projectTasks = [];

async function loadProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  const projects = await response.json();
  projectContainer.replaceChildren();
  const filter = document.querySelector('#project-filter').value;
  for (const project of projects.filter(p => Boolean(p.archived) === (filter === 'Archived'))) {
    const row = document.createElement('div');
    row.className = 'project-row';
    row.dataset.testid = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => navigate(`/projects/${project.id}`));
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const toggle = document.createElement('button');
    toggle.type = 'button';
    toggle.textContent = project.archived ? 'Restore project' : 'Archive project';
    toggle.addEventListener('click', async () => {
      await fetch(`/api/projects/${project.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ archived: !project.archived }) });
      await loadProjects();
    });
    row.append(name, summary, open, toggle);
    projectContainer.append(row);
  }
}

async function showRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (!match) {
    listSection.hidden = false;
    detailSection.hidden = true;
    await loadProjects();
    return;
  }
  const response = await fetch('/api/projects');
  const projects = await response.json();
  const project = projects.find(item => String(item.id) === match[1]);
  if (!project) {
    navigate('/', true);
    return;
  }
  document.querySelector('#detail-name').textContent = project.name;
  document.querySelector('#archived-notice').hidden = !project.archived;
  document.querySelector('#task-title').disabled = Boolean(project.archived);
  document.querySelector('#task-form button').disabled = Boolean(project.archived);
  document.querySelector('#new-project-name').disabled = Boolean(project.archived);
  document.querySelector('#rename-form button').disabled = Boolean(project.archived);
  document.querySelector('#new-project-name').value = project.name;
  activeProjectId = project.id;
  listSection.hidden = true;
  detailSection.hidden = false;
  await loadTasks();
}

function navigate(path, replace = false) {
  if (replace) history.replaceState({}, '', path);
  else history.pushState({}, '', path);
  showRoute();
}

document.querySelector('#create-form').addEventListener('submit', async event => {
  event.preventDefault();
  errorMessage.hidden = true;
  const input = document.querySelector('#project-name');
  const response = await fetch('/api/projects', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: input.value })
  });
  if (!response.ok) {
    const result = await response.json();
    errorMessage.textContent = result.error || 'Unable to create project';
    errorMessage.hidden = false;
    return;
  }
  input.value = '';
  await loadProjects();
});

async function loadTasks() {
  const response = await fetch(`/api/projects/${activeProjectId}/tasks`);
  if (!response.ok) return;
  projectTasks = await response.json();
  renderTasks();
}

function renderTasks() {
  const filter = document.querySelector('#task-filter').value;
  taskContainer.replaceChildren();
  for (const task of projectTasks) {
    if (filter === 'Open' && task.completed || filter === 'Completed' && !task.completed) continue;
    const row = document.createElement('div');
    row.className = 'task-row';
    row.dataset.testid = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = Boolean(task.completed);
    checkbox.disabled = document.querySelector('#archived-notice').hidden === false;
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      const response = await fetch(`/api/projects/${activeProjectId}/tasks/${task.id}`, {
        method: 'PATCH', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ completed: checkbox.checked })
      });
      if (response.ok) {
        const updated = await response.json();
        task.completed = updated.completed;
        renderTasks();
      }
    });
    row.append(title, checkbox);
    taskContainer.append(row);
  }
}

document.querySelector('#task-filter').addEventListener('change', renderTasks);
document.querySelector('#project-filter').addEventListener('change', loadProjects);
document.querySelector('#task-form').addEventListener('submit', async event => {
  event.preventDefault();
  const error = document.querySelector('#task-error-message');
  error.hidden = true;
  const input = document.querySelector('#task-title');
  const response = await fetch(`/api/projects/${activeProjectId}/tasks`, {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ title: input.value })
  });
  if (!response.ok) {
    const result = await response.json();
    error.textContent = result.error || 'Unable to create task';
    error.hidden = false;
    return;
  }
  input.value = '';
  await loadTasks();
});

document.querySelector('#rename-form').addEventListener('submit', async event => {
  event.preventDefault();
  const error = document.querySelector('#rename-error');
  error.hidden = true;
  const input = document.querySelector('#new-project-name');
  const response = await fetch(`/api/projects/${activeProjectId}`, {
    method: 'PATCH', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ name: input.value })
  });
  if (!response.ok) {
    const result = await response.json();
    error.textContent = result.error || 'Unable to rename project';
    error.hidden = false;
    return;
  }
  await showRoute();
});

document.querySelector('#back-button').addEventListener('click', () => navigate('/'));
window.addEventListener('popstate', showRoute);
showRoute();

